export function handleInput(input: string): void {
  const gameStatus = getGameStatus();
  if (!gameStatus) return;
  if (gameStatus.isWon || gameStatus.isLost) return;

  const { guessedLetters, remainingTries, word } = gameStatus;
  const guessed = new Set(guessedLetters);

  let hasMatch = false;
  for (let i = 0; i < word.length; i++) {
    if (guessed.has(word[i])) {
      hasMatch = true;
      document.getElementById(`letter-${i}`)?.textContent = word[i];
    }
  }

  if (!hasMatch && remainingTries > 0) {
    document.getElementById('hangmanStage')?.classList.add('stage-' + (14 - remainingTries));
    decrementTries();
  } else if (remainingTries <= 0) {
    revealWord();
    document.getElementById('hangmanStage')?.classList.add('stage-14');
    gameOver();
  } else {
    incrementTries();
  }

  const progress = document.getElementById('progress');
  if (progress) {
    const total = word.length;
    const guessedCount = guessed.size;
    progress.style.width = `${(guessedCount / total) * 100}%`;
    progress.textContent = `${guessedCount}/${total}`;
  }
}

export function revealWord(): void {
  const letters = document.querySelectorAll('.letter');
  letters.forEach((letter) => {
    letter.textContent = letter.dataset.letter;
  });
}

export function gameOver(): void {
  const result = document.getElementById('result');
  if (getGameStatus().isWon) {
    result.textContent = '🎉 You won! 🎉';
  } else {
    result.textContent = '💥 Game over! 💥';
  }
  document.querySelectorAll('.letter').forEach((letter) => {
    letter.classList.add('revealed');
  });
  document.getElementById('hangmanStage')?.classList.add('stage-14');
}

export function decrementTries(): void {
  const tries = parseInt(document.getElementById('tries')?.textContent || '0');
  if (tries > 0) {
    document.getElementById('tries')?.textContent = (tries - 1).toString();
  }
}

export function incrementTries(): void {
  const tries = parseInt(document.getElementById('tries')?.textContent || '0');
  if (tries < 13) {
    document.getElementById('tries')?.textContent = (tries + 1).toString();
  }
}

export function resetGame(): void {
  revealWord();
  document.querySelectorAll('.letter').forEach((letter) => {
    letter.textContent = '';
    letter.classList.remove('revealed');
  });
  document.getElementById('hangmanStage')?.classList.remove('stage-14');
  document.getElementById('tries')?.textContent = '13';
  document.getElementById('result')?.textContent = '';
  document.getElementById('progress')?.textContent = '0/0';
}

