let gameRunning = false;
let currentWord = '';
let guessedLetters = new Set<string>();

function guess(letter: string) {
  if (!gameRunning) return;
  if (guessedLetters.has(letter)) return;

  guessedLetters.add(letter);
  const wordArray = currentWord.split('');
  for (let i = 0; i < wordArray.length; i++) {
    if (wordArray[i] === letter) {
      wordArray[i] = letter;
    }
  }
  currentWord = wordArray.join('');

  document.getElementById('wordDisplay')!.textContent = currentWord;
  document.getElementById('livesDisplay')!.textContent = `Lives: ${5 - missedLetters.length}`;

  if (currentWord.split('').every((l) => l !== '_')) {
    alert('🎉 You won! The word was: ' + currentWord);
    gameRunning = false;
  } else if (missedLetters.length === 5) {
    alert('💥 You lost! The word was: ' + currentWord);
    gameRunning = false;
  }
}

function missedLetters(): string[] {
  return Array.from(guessedLetters).filter((l) => !currentWord.includes(l));
}

function startGame() {
  gameRunning = true;
  currentWord = 'elephant';
  guessedLetters.clear();
  document.getElementById('wordDisplay')!.textContent = '_ '.repeat(currentWord.length);
  document.getElementById('livesDisplay')!.textContent = 'Lives: 5';
}
